theme.css:
/* Stellar by HTML5 UP | html5up.net | @ajlkn | CC BY 3.0.
 * Adapted for ImmichPager; composition, typography and accessibility modified. */
:scope { background:linear-gradient(45deg,#935d8c,#5f4d93); padding-block:40px; }
.ip-hero { padding:0 24px; }
.ip-hero .ip-header { color:#ffffff; --pager-muted:#ffffff; padding:48px 16px; }
.ip-hero .ip-navigation { background:#ffffff; color:#3f3f3f; border:0; border-radius:8px 8px 0 0; padding:16px; margin:0; }
.ip-hero .ip-banner { width:180px; height:180px; border-radius:50%; margin:32px auto; }
.page-blocks { max-width:1120px; width:calc(100% - 48px); margin:auto; background:#ffffff; border-radius:8px; }
.ip-block::before { display:none; }
.ip-block .block-heading { font-weight:400; }
.ip-block .block-heading::after { content:''; display:block; width:100px; height:2px; margin-top:20px; background:linear-gradient(90deg,#efa8b0,#a89cc8,#8cc9f0); }
.ip-footer { color:#ffffff; }
@media(max-width:760px) { :scope { padding-block:16px; } .ip-hero { padding-inline:16px; } .page-blocks { width:calc(100% - 32px); } }

.ip-description { opacity:1; }

.ip-albums:not(.tiles) .ip-album-info p { opacity:1; color:var(--pager-muted); }
.ip-albums.tiles .ip-album-info p { opacity:1; color:#ffffff; }
